    if not input_data:
        return

    iterator = iter(input_data)
    N = int(next(iterator))
    K = int(next(iterator))
    U = int(next(iterator))

    cartelas_com_numero = [[] for _ in range(U + 1)]

    for c in range(1, N + 1):
