    remaining = [K] * (N + 1)
    winners = []

    for _ in range(U):
        drawn = int(next(iterator))
        for c in cartelas_com_numero[drawn]:
            remaining[c] -= 1
            if remaining[c] == 0:
                winners.append(c)
        if winners:
            break

    winners.sort()
    print(' '.join(map(str, winners)))

